<template>
  <view class="payment-success-page">
    <!-- 支付成功卡片 -->
    <view class="card success-card">
      <view class="icon">
        <text class="icon-check">✓</text>
      </view>
      <text class="main-title">支付成功！</text>
      <text class="desc">您的陪诊订单已确认，陪诊员将在10-30分钟内与您联系</text>
      <!-- 新增：查看订单详情按钮 -->
      <button class="view-order-btn" @click="goToOrderDetail">查看订单详情</button>
    </view>

    <!-- 订单信息 -->
    <view class="card order-info">
      <view class="title"><text class="iconfont">📝</text> 订单信息</view>
      <view class="info-item">
        <text class="label">订单编号</text>
        <text class="value">{{ orderData.orderNo }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付金额</text>
        <text class="value">¥{{ formatAmount(orderData.totalPrice) }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付时间</text>
        <text class="value">{{ payTime }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付方式</text>
        <text class="value">微信支付</text>
      </view>
      <view class="info-item">
        <text class="label">订单状态</text>
        <text class="value">{{ orderData.orderStatusDesc }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付状态</text>
        <text class="value">{{ orderData.paymentStatusDesc }}</text>
      </view>
    </view>

    <!-- 服务详情 -->
    <view class="card service-detail">
      <view class="title"><text class="iconfont">💼</text> 服务详情</view>
      <view class="info-item">
        <text class="label">陪诊师</text>
        <text class="value">{{ orderData.attendantName }}</text>
      </view>
      <view class="info-item">
        <text class="label">联系电话</text>
        <text class="value">{{ orderData.attendantPhone }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊时间</text>
        <text class="value">{{ orderData.serviceDate }} {{ orderData.serviceTime }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊医院</text>
        <text class="value">{{ orderData.hospital }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊人</text>
        <text class="value">{{ orderData.patientName }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊人电话</text>
        <text class="value">{{ orderData.patientPhone }}</text>
      </view>
      <view class="info-item">
        <text class="label">服务类型</text>
        <text class="value">{{ orderData.serviceTypeName }}</text>
      </view>

      <view class="info-item" v-if="orderData.symptoms && orderData.symptoms.length">
        <text class="label">症状</text>
        <text class="value">{{ orderData.symptoms.join(', ') }}</text>
      </view>
      <!-- 修改：显示 otherRequirement 字段 -->
      <view class="info-item">
        <text class="label">其他要求</text>
        <text class="value">{{ orderData.otherRequirement || '无' }}</text>
      </view>

    </view>
  </view>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { get } from '@/utils/api.js'; // 导入api

const orderData = ref({});
const payTime = ref(''); // 动态支付时间

// 获取订单详情 (使用完整信息接口)
const fetchOrderDetail = async (orderNo) => {
  try {
    console.log('【PaymentSuccessPage】正在调用后端接口获取订单完整信息:', orderNo);
    const response = await get(`/ai/guide/orders/${orderNo}/complete-info`);

    console.log('【PaymentSuccessPage】后端返回的订单完整数据:', response.data);

    if (response && response.data) {
      // 直接赋值后端返回的完整数据
      orderData.value = response.data;
    } else {
      console.warn('【PaymentSuccessPage】后端返回数据为空或格式不正确:', response);
      uni.showToast({
        title: '获取订单信息失败',
        icon: 'none'
      });
    }
  } catch (error) {
    console.error('【PaymentSuccessPage】获取订单完整信息失败:', error);
    uni.showToast({
      title: '网络错误，获取订单信息失败',
      icon: 'none'
    });
  }
};

// 页面加载
onLoad(async (options) => {
  console.log('【PaymentSuccessPage】页面加载参数:', options);
  // 获取当前支付时间
  const now = new Date();
  payTime.value = now.getFullYear() + '-' +
                   String(now.getMonth() + 1).padStart(2, '0') + '-' +
                   String(now.getDate()).padStart(2, '0') + ' ' +
                   String(now.getHours()).padStart(2, '0') + ':' +
                   String(now.getMinutes()).padStart(2, '0') + ':' +
                   String(now.getSeconds()).padStart(2, '0');

  // 获取 orderNo
  const orderNo = options.orderNo || '';
  console.log('【PaymentSuccessPage】订单号:', orderNo);

  if (!orderNo) {
    console.error('【PaymentSuccessPage】缺少订单号参数');
    uni.showToast({
      title: '订单号错误',
      icon: 'none'
    });
    // 可以跳转回首页或其他页面
    uni.redirectTo({
      url: '/pages/index/index'
    });
    return;
  }

  // 获取订单完整详情
  await fetchOrderDetail(orderNo);

  // ========== 修改：将订单添加到全局订单列表，确保数据结构匹配 order.vue ==========
  // 1. 从本地存储获取现有的订单列表
  let existingOrders = uni.getStorageSync('all_orders') || [];
  console.log('【调试】当前已存在的订单列表:', existingOrders);

  // 2. 创建符合 order.vue 需求的订单对象结构
  // 注意：需要解析 serviceTime 为 date 和 time
  const serviceTimeParts = orderData.value.serviceTime ? orderData.value.serviceTime.split(' ') : [];
  const serviceDate = serviceTimeParts[0] || '未知日期';
  const startTime = serviceTimeParts[1] || '未知时间';

  // 确保金额格式正确 (从分转为元字符串)
  const formattedPrice = `¥${formatAmount(orderData.value.totalPrice)}`;

  // --- 关键修改：确定陪诊师头像字段 ---
  // 优先使用 avatarUrl (来自 OrderConfirmPage 传递)，否则回退到 attendantAvatar 或默认值
  const attendantAvatarToUse = orderData.value.attendantAvatar || '/static/default-avatar.jpg';
  // --- 结束修改 ---

  const orderForList = {
    id: orderData.value.orderNo, // 使用订单号作为唯一ID
    orderId: orderData.value.orderNo, // 与 OrderDetailPage 兼容
    serviceType: orderData.value.serviceTypeName || '普通陪诊',
    hospitalName: orderData.value.hospital || '未知医院',
    serviceDate: serviceDate, // 提取日期部分
    startTime: startTime, // 提取时间部分
    status: orderData.value.orderStatusDesc === '待接单' ? 'assigned' : 'pending', // <--- 修改：根据订单状态设置
    price: formattedPrice, // 确保格式正确
    attendantAvatar: attendantAvatarToUse, // <--- 关键：使用确定的头像路径
    doctorAvatar: attendantAvatarToUse, // 兼容旧字段，如果 order.vue 仍在使用
    attendantName: orderData.value.attendantName, // 新增：陪诊师姓名
    doctorName: orderData.value.attendantName || '未知陪诊师', // 兼容旧字段
    rating: orderData.value.attendantScore || 5, // 假设默认评分
    // 添加其他可能需要的字段
    amount: orderData.value.totalPrice, // 以分为单位的金额
    attendantPhone: orderData.value.attendantPhone, // 陪诊师电话
    contactPerson: orderData.value.patientName, // 就诊人
    payTime: orderData.value.createTime || payTime.value, // 支付时间 (使用创建时间)
    paymentMethod: '微信支付' // 支付方式
  };

  // 3. 检查是否已存在相同ID的订单 (避免重复)
  const exists = existingOrders.some(order => order.id === orderForList.id);
  if (!exists) {
    existingOrders.unshift(orderForList); // 添加到列表开头，最新订单在前
    console.log('【调试】添加新订单到列表:', orderForList);
  } else {
    console.log('【调试】订单已存在，未添加:', orderForList.id);
    // 如果订单已存在，可以考虑更新其状态等信息
    const index = existingOrders.findIndex(order => order.id === orderForList.id);
    if (index !== -1) {
      // 更新现有订单信息，但保留其可能已经改变的状态（例如，如果它已经被接单）
      // 这里可以更精细地判断是否需要更新状态
      // 例如，只有当原状态是 'pending' 时，才更新为 'assigned'
      const currentStatus = existingOrders[index].status;
      // 如果当前状态已经是 'assigned', 'in_progress', 'completed', 'cancelled'，则不更新为 'assigned'
      if (currentStatus === 'pending' || currentStatus === 'completed') { // 'completed' 是之前的错误状态，也应更新
        existingOrders[index] = {
          ...existingOrders[index],
          ...orderForList
        };
        console.log('【调试】已更新现有订单状态:', orderForList.id);
      } else {
        // 否则，只更新其他信息，不更新状态
        const { status: _, ...orderForListWithoutStatus } = orderForList; // 解构排除 status
        existingOrders[index] = {
          ...existingOrders[index],
          ...orderForListWithoutStatus
        };
        console.log('【调试】已更新现有订单其他信息，保留原状态:', orderForList.id, currentStatus);
      }
    }
  }

  // 4. 保存更新后的订单列表
  uni.setStorageSync('all_orders', existingOrders);
  console.log('【调试】已保存更新后的订单列表:', existingOrders);
  // ========== 结束修改 ==========
});

/**
 * 格式化金额 (分 -> 元)
 * @param {number} amountInCents - 以分为单位的金额
 * @returns {string} 格式化后的金额字符串 (保留两位小数)
 */
const formatAmount = (amountInCents) => {
  // 确保传入的是数字类型
  const amount = Number(amountInCents);
  // 检查是否为有效数字
  if (isNaN(amount)) {
    return '0.00';
  }
  // 除以100转换为元，并使用 toFixed 保留两位小数
  // toFixed 返回字符串类型，保证了精度
  return amount.toFixed(2);
};

/**
 * 跳转到订单详情页的方法 (修改：使用 redirectTo)
 */
const goToOrderDetail = () => {
  // 确保有订单号
  if (orderData.value.orderNo) {
    // 使用 uni.redirectTo 替代 uni.navigateTo，替换当前页面栈
    uni.redirectTo({
      url: `/pages/OrderDetailPage/OrderDetailPage?orderNo=${encodeURIComponent(orderData.value.orderNo)}`
    });
  } else {
    uni.showToast({ title: '无法跳转：缺少订单号', icon: 'none' });
  }
};
</script>

